<script lang="ts">
 import {onMount} from 'svelte';import {api,websocketUrl} from '../lib/api.js';import {chooseContext,type WorkbenchState} from '../lib/workbench-state.js';export let state:WorkbenchState;let contexts:any[]=[];let selected='local';let status='Discovering FNGK…';let repository='/workspace';const sockets=new Set<WebSocket>();
 async function load(){state.setConnection({phase:'checking',message:'Discovering installed FNGK…'});try{const value=await api<any>('/api/contexts');contexts=value.contexts;selected=chooseContext(contexts,state.snapshot());state.setContext(selected,false);if(value.state.compatible){status=`${value.state.profile??'default'} · ${value.state.version}`;state.setConnection({phase:'connected',message:`Connected to ${value.state.profile??'default'}`,profile:value.state.profile,version:value.state.version});}else{status=value.state.reason??'FNGK unavailable';state.setConnection({phase:value.state.login==='required'?'authentication-required':'unavailable',message:status,profile:value.state.profile,version:value.state.version});}}catch(error){status=(error as Error).message;contexts=[{id:'local',name:'Atlas process host (not FNGK)',kind:'local',online:true}];selected='local';state.setContext('local',false);state.setConnection({phase:'unavailable',message:status});}}
 function choose(id:string){selected=id;state.setContext(id);window.dispatchEvent(new CustomEvent('atlas:context',{detail:id}));}
 function scan(){const socket=new WebSocket(websocketUrl(`/api/discovery/scan?contextId=${encodeURIComponent(selected)}`));let failed=false;sockets.add(socket);status='Scanning host…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code;}state.appendActivity(`${v.type} · ${v.scanned??''}`);};socket.onclose=()=>{sockets.delete(socket);if(!failed){status='Scan complete';window.dispatchEvent(new Event('atlas:graph-refresh'));}};}
 function analyze(){if(!repository.trim())return;const socket=new WebSocket(websocketUrl(`/api/analysis/repository?contextId=${encodeURIComponent(selected)}&path=${encodeURIComponent(repository)}`));let completed=false,failed=false;sockets.add(socket);status='Analyzing repository…';socket.onmessage=e=>{const v=JSON.parse(e.data);if(v.type==='error'){failed=true;status=v.message??v.code;}state.appendActivity(`${v.type} · ${v.index?.summary?.functions??v.nodes?.length??''}`);if(v.type==='analysis_complete'){completed=true;status=`${v.index.summary.functions} functions mapped`;window.dispatchEvent(new Event('atlas:graph-refresh'));}};socket.onclose=()=>{sockets.delete(socket);if(!completed&&!failed)status='Analysis stopped';};}
 onMount(()=>{void load();return()=>{for(const socket of sockets)socket.close();sockets.clear();};});
</script>
<aside class="navigator"><div class="brand"><div class="brand-mark">A</div><div><strong>ATLAS</strong><small>FNGK workbench</small></div></div><div class="section-title">CONTEXTS</div>{#each contexts as item}<button class:active={item.id===selected} class="context" onclick={()=>choose(item.id)}><span class:online={item.online}></span><div><b>{item.name}</b><small>{item.kind??'machine'} · {item.routes?.[0]?.effectiveIdentity??(item.online?'reachable':'offline')}</small></div></button>{/each}<div class="section-title">REPOSITORY</div><div class="repository"><input bind:value={repository} aria-label="Repository path" placeholder="/path/to/repository"><button onclick={analyze}>Map code</button></div><div class="navigator-actions"><button onclick={scan}>Scan selected host</button><button onclick={load}>Refresh namespace</button></div><div class="context-status">{status}</div><div class="navigator-spacer"></div><div class="rail"><button title="Explorer" class="active">⌘</button><button title="Search">⌕</button><button title="Source control">⑂</button><button title="Coverage">◔</button><button title="Settings">⚙</button></div></aside>
